统一打印函数：
void print(std::span<int> values) {
    for (const auto& value : values) {
        std::cout << value << ' ';
    }
    std::cout << std::endl;
}

该函数可以接收：
std::vector v{11, 22, 33, 44, 55, 66};
std::array arr{5, 4, 3, 2, 1};
int carr[]{9, 8, 7, 6, 5};
print(v);
print(arr);
print(carr);
